// src/renderer/src/features/workout/services/prDetection.ts
async function detectPrs(input) {
	const { exerciseId, weight, reps } = input;
	if (weight <= 0 || reps <= 0) return [];
	const existing = await db.personalRecords.where("exerciseId").equals(exerciseId).toArray();
	const best = (type) => existing.filter((p) => p.type === type).reduce((m, p) => Math.max(m, p.value), 0);
	const found = [];
	const est = epley1rm(weight, reps);
	const volume = weight * reps;
	if (weight > best("weight")) found.push({
		type: "weight",
		value: weight,
		label: "Weight PR"
	});
	if (reps > best("reps") && weight >= best("weight") * .9) found.push({
		type: "reps",
		value: reps,
		label: `Rep PR @ ${weight}`
	});
	if (est > best("estimated_1rm")) found.push({
		type: "estimated_1rm",
		value: est,
		label: "Est. 1RM PR"
	});
	if (volume > best("volume")) found.push({
		type: "volume",
		value: volume,
		label: "Set volume PR"
	});
	return found;
}
async function savePrs(exerciseId, setId, prs) {
	const now = (/* @__PURE__ */ new Date()).toISOString();
	const rows = prs.map((pr) => ({
		id: crypto.randomUUID(),
		exerciseId,
		type: pr.type,
		value: pr.value,
		setId,
		achievedAt: now
	}));
	if (rows.length) await db.personalRecords.bulkPut(rows);
	return rows;
}
