async function importAllJson(raw) {
	const data = JSON.parse(raw);
	await db.transaction("rw", db.tables, async () => {
		if (data.userProfile) await db.userProfile.bulkPut(data.userProfile);
		if (data.gymProfiles) await db.gymProfiles.bulkPut(data.gymProfiles);
		if (data.exercisePrefs) await db.exercisePrefs.bulkPut(data.exercisePrefs);
		if (data.workouts) await db.workouts.bulkPut(data.workouts);
		if (data.workoutExercises) await db.workoutExercises.bulkPut(data.workoutExercises);
		if (data.sets) await db.sets.bulkPut(data.sets);
		if (data.personalRecords) await db.personalRecords.bulkPut(data.personalRecords);
		if (data.bodyMetrics) await db.bodyMetrics.bulkPut(data.bodyMetrics);
		if (data.templates) await db.templates.bulkPut(data.templates);
		if (data.programs) await db.programs.bulkPut(data.programs);
		if (data.appSettings) await db.appSettings.bulkPut(data.appSettings);
		if (data.customExercises) await db.exercises.bulkPut(data.customExercises);
	});
}
async function exportHistoryCsv() {
	const workouts = await db.workouts.where("status").equals("completed").toArray();
	const lines = ["id,startedAt,endedAt,rating,source,notes"];
	for (const w of workouts) lines.push([
		w.id,
		w.startedAt,
		w.endedAt ?? "",
		w.rating ?? "",
		w.source,
		JSON.stringify(w.notes)
	].join(","));
	return lines.join("\n");
}
async function resetAllData() {
	await db.delete();
	await db.open();
}
/** Dev helper: 8 weeks of fake completed sessions for charts */
async function seedDemoHistory() {
	const exercises = await db.exercises.limit(20).toArray();
	if (exercises.length === 0) return;
	const gym = await db.gymProfiles.filter((g) => g.isActive).first();
	if (!gym) return;
	for (let week = 0; week < 8; week++) for (let day = 0; day < 3; day++) {
		const ended = subDays(/* @__PURE__ */ new Date(), week * 7 + day * 2);
		const id = crypto.randomUUID();
		await db.workouts.put({
			id,
			startedAt: (/* @__PURE__ */ new Date(ended.getTime() - 36e5)).toISOString(),
			endedAt: ended.toISOString(),
			status: "completed",
			gymProfileId: gym.id,
			rating: 3 + day % 3,
			notes: "Seeded",
			source: "adaptive",
			templateId: null,
			programId: null
		});
		const pick = exercises[(week * 3 + day) % exercises.length];
		const weId = crypto.randomUUID();
		await db.workoutExercises.put({
			id: weId,
			workoutId: id,
			exerciseId: pick.id,
			order: 0,
			supersetGroup: null,
			notes: "",
			reasoning: "Seeded history",
			locked: false
		});
		for (let s = 0; s < 3; s++) {
			const weight = 40 + week * 2 + s;
			const setId = crypto.randomUUID();
			await db.sets.put({
				id: setId,
				workoutExerciseId: weId,
				order: s,
				type: "working",
				targetWeight: weight,
				targetReps: 8,
				weight,
				reps: 8 - s % 2,
				rpe: 7 + s % 3,
				completedAt: ended.toISOString()
			});
			if (s === 0) await db.personalRecords.put({
				id: crypto.randomUUID(),
				exerciseId: pick.id,
				type: "estimated_1rm",
				value: weight * (1 + 8 / 30),
				setId,
				achievedAt: ended.toISOString()
			});
		}
	}
}
